#include <map>

struct device_axis;
struct game_control {
    int device_id;
    int control_id;
    device_axis *axes;
    game_control(const game_control &);
};

template<class T>
struct my_allocator : public allocator<T> {};

typedef pair<const int, game_control> value_type;
typedef _Rb_tree<int, value_type, _Select1st<value_type>, less<int>, my_allocator<game_control> > tree_type;

template tree_type::iterator tree_type::_M_insert(_Rb_tree_node_base *, _Rb_tree_node_base *, const value_type &);
